use vstd::prelude::*;

verus! {
    // reverse returns a new Vec<i8> containing the elements of s in reverse order.
    // Ensures the output has the same length as the input, and for each valid index k,
    // rev[k] == s[n-1-k].
    fn reverse(s: Vec<i8>) -> (rev: Vec<i8>)
        ensures rev.len() == s.len(),
        ensures forall |k: int| 0 <= k && k < rev.len() as int ==>
            rev.index(k as nat) == s.index((s.len() as int - 1 - k) as nat),
    {
        let n = s.len();
        let mut rev = Vec::<i8>::with_capacity(n);
        let mut i: usize = 0;
        while i < n
            invariant i <= n,
            invariant rev.len() == i,
            invariant forall |k: int| 0 <= k && k < rev.len() as int ==>
                rev.index(k as nat) == s.index((n as int - 1 - k) as nat),
            decreases n - i,
        {
            // Take the element from s at position n-1-i and push it onto rev
            let x = s.index((n - 1 - i) as nat);
            rev.push(x);
            i += 1;
        }
        rev
    }
}

